  "${proposal.undecided.length} fields have two equally likely candidates: those are left for you, in the other tabs.":
    "${proposal.undecided.length} फ़ील्ड में दो समान रूप से संभावित विकल्प हैं: वे आपके लिए बाकी टैब में छोड़ दिए गए हैं।",
  "${quante} coming up": "${quante} आने वाले",
