  "${spente} entities are disabled in Home Assistant: enable them there to see them here too.":
    "${spente} एंटिटी Home Assistant में अक्षम हैं: उन्हें यहाँ भी देखने के लिए वहाँ सक्षम करें।",
  "${totale} lights": "${totale} बत्तियाँ",
  "${trovate.length} cartridges found": "${trovate.length} कार्ट्रिज मिले",
  "${value} channels": "${value} चैनल",
  "${value} d ago": "${value} दिन पहले",
  "${value} floors": "${value} मंज़िलें",
  "${value} h ago": "${value} घंटे पहले",
  "${value} live": "${value} सक्रिय",
  "${value} min ago": "${value} मिनट पहले",
  "${value} offline": "${value} ऑफ़लाइन",
  "${value} units": "${value} यूनिट",
  "${valvola.aperta}% open": "${valvola.aperta}% खुला",
  "${valvola.chiusa}% closed": "${valvola.chiusa}% बंद",
  "(bottom left)": "(नीचे बाईं ओर)",
  "(cover entities). They appear on the 🪟 Windows page, grouped by floor and room.":
    "(cover इकाइयाँ)। ये 🪟 खिड़कियाँ पृष्ठ पर मंज़िल और कमरे के अनुसार समूहित दिखती हैं।",
  "(enables automatic room grouping).": "(कमरे के अनुसार अपने आप समूह बनाना चालू करता है)।",
  "(optional): only this HA user will see the ⚙️ Configuration page. Leave it empty to show it to everyone.":
    "(वैकल्पिक): ⚙️ कॉन्फ़िगरेशन पेज केवल यही HA उपयोगकर्ता देखेगा। सबको दिखाने के लिए खाली छोड़ दें।",
  "(with HACS it survives updates).": "(HACS के साथ यह अपडेट के बाद भी बनी रहती है)।",
  "+${extra} more items": "+${extra} और आइटम",
  ', name it (e.g. "Dashboard") and paste it here:':
    ', उसे नाम दें (जैसे "Dashboard") और यहाँ चिपकाएँ:',
  ", so it works even with": ", इसलिए यह उन पर भी काम करता है जो",
  ", with a condition,": ", एक शर्त के साथ,",
