  '. Empty items will show "—".': '. खाली प्रविष्टियाँ "—" दिखाएँगी।',
  ". If values stay at zero, make sure the entities have":
    ". अगर मान शून्य पर ही रहें, तो देखें कि इकाइयों में",
  "1 alert in force": "1 अलर्ट लागू",
