  "Earthquakes · Weather · Lightning · Pollen · Flights": "भूकंप · मौसम · बिजली · पराग · उड़ानें",
  "Earthquakes, civil protection warnings, lightning, pollen, thermal comfort and flights overhead: for each one pick the sensor its integration already brought into Home Assistant. No field is required and each one is enough on its own: the page shows only the sources you have. The dashboard calls no service, it reads what is there.":
    "भूकंप, नागरिक सुरक्षा चेतावनियाँ, बिजली, पराग, तापीय आराम और ऊपर से गुज़रती उड़ानें: हर एक के लिए वह सेंसर चुनें जो उसका इंटीग्रेशन पहले ही Home Assistant में लाया है। कोई फ़ील्ड अनिवार्य नहीं और हर एक अकेले काफ़ी है: पेज सिर्फ़ वही स्रोत दिखाता है जो आपके पास हैं। डैशबोर्ड कोई सेवा नहीं बुलाता, जो है उसे पढ़ता है।",
