  "Enough on its own: on and off, no numbers.": "अकेले ही काफ़ी: चालू और बंद, बिना संख्याओं के।",
  "Enough on its own: the card says on and off, and does not pretend to know the degrees.":
    "अकेला ही काफ़ी: कार्ड चालू और बंद बताता है, और डिग्री जानने का दिखावा नहीं करता।",
