  "Flue extractor fan": "धुआँ निकासी पंखा",
  "Flue gas": "धुआँ",
  "Flue gas fan": "धुएँ का पंखा",
  "Flue gas temperature": "धुएँ का तापमान",
  "Followed train": "अनुसरित ट्रेन",
  Food: "भोजन",
  "Food level": "भोजन का स्तर",
  "Food running low": "भोजन ख़त्म होने वाला है",
  "For each item enter": "हर प्रविष्टि के लिए लिखें",
  "For every source, Total energy meter is the cumulative Recorder source (normally state_class: total_increasing). It is not a period value: day, month and year are calculated as final Recorder sum minus initial Recorder sum, so meter resets are preserved. Period sensors are optional current-period overrides.":
    "हर स्रोत के लिए कुल ऊर्जा मीटर ही Recorder का संचयी स्रोत है (आमतौर पर state_class: total_increasing)। यह अवधि का मान नहीं है: दिन, महीना और साल Recorder के अंतिम योग में से आरंभिक योग घटाकर निकाले जाते हैं, इसलिए मीटर के रीसेट सुरक्षित रहते हैं। अवधि सेंसर मौजूदा अवधि के लिए वैकल्पिक विकल्प हैं।",
  "For fridge and freezer: shows the temperature strip instead of the power bar.":
    "फ़्रिज और फ़्रीज़र के लिए: शक्ति पट्टी के बजाय तापमान पट्टी दिखाता है।",
  "For lights you only want to see, with no accidental taps: the row stays where it is, the button stops responding.":
    "उन बत्तियों के लिए जिन्हें आप केवल देखना चाहते हैं, बिना गलती से छुए: पंक्ति वहीं रहती है, बटन जवाब देना बंद कर देता है।",
  "For sockets that must not be switched off: the fridge, the modem, the freezer. The row stays where it is, the button stops responding.":
    "उन सॉकेट के लिए जिन्हें बंद नहीं करना चाहिए: फ़्रिज, मोडेम, फ़्रीज़र। पंक्ति अपनी जगह रहती है, बटन काम करना बंद कर देता है।",
  "For this window only: resting at this percentage or below counts as closed. Empty, the house threshold at the top applies.":
    "केवल इस खिड़की के लिए: इस प्रतिशत या इससे नीचे रुकना बंद माना जाता है। खाली छोड़ें तो ऊपर की घर की सीमा लागू होती है।",
  "For this window only: when its room's humidity goes above this level, the card says to open it to air out. Empty, the house threshold at the top applies; zero turns the advice off on this window.":
    "सिर्फ़ इस खिड़की के लिए: जब इसके कमरे की नमी इस स्तर से ऊपर जाती है, कार्ड हवा देने के लिए खोलने को कहता है। खाली हो तो ऊपर लिखी घर की सीमा लागू; शून्य इस खिड़की पर सलाह बंद करता है।",
  "For those without a panel: an alarm built with ESPHome, with scripts or with a list of modes. Each button below shows up in the Security section and on the Home tile, next to the panel's own — and when there is no panel, in their place.":
    "उनके लिए जिनके पास पैनल नहीं है: ESPHome, स्क्रिप्ट या मोड की सूची से बना अलार्म। यहाँ का हर बटन सुरक्षा अनुभाग में और होम टाइल पर दिखता है, पैनल के बटनों के साथ — और पैनल न हो तो उनकी जगह।",
  "For what recharges instead of being replaced: the wall tablet, a power bank. The two entities are number.* or input_number.*, the ones the device exposes to say where it starts again and where it stops. Leave them empty and this stays a battery like the others.":
    "जो बदला नहीं जाता बल्कि दोबारा चार्ज होता है, उसके लिए: दीवार का टैबलेट, पावर बैंक। दोनों एंटिटी number.* या input_number.* हैं — वही जो डिवाइस बताता है कि वह कहाँ से फिर शुरू होता है और कहाँ रुकता है। खाली छोड़ दें तो यह बाकी बैटरियों जैसी ही रहेगी।",
  "Force (ignore rain)": "ज़बरदस्ती चलाएँ (बारिश अनदेखी करें)",
  Forest: "वन",
  "Found next to the appliance — one tap adds them:":
    "उपकरण के पास मिले — एक टैप से जुड़ जाते हैं:",
  "Found next to the player — one tap adds them:": "प्लेयर के पास मिले — एक टैप से जुड़ जाएँगे:",
  "Found next to the robot — one tap adds them:": "रोबोट के पास मिले — एक टैप से जुड़ जाते हैं:",
  "Fountain filter": "फ़व्वारे का फ़िल्टर",
  "Four sensors of your choosing: the ones you actually read to decide, not a house average. The typical one is outdoors, the one you go by for the indoor units. The unit comes from Home Assistant, and a sensor you do not name is a pill that does not show up.":
    "आपके चुने हुए चार सेंसर: वे जिन्हें आप सचमुच देखकर तय करते हैं, घर का औसत नहीं। आम तौर पर बाहर वाला, जिसके हिसाब से अंदर की यूनिट सेट करते हैं। इकाई Home Assistant बताता है, और जो सेंसर आप नहीं बताते वह न दिखने वाला कार्ड है।",
