  "Groups are the popup opened from a flow circle. Their children are the cards shown inside, such as Oven, Fridge or Dishwasher.":
    "समूह वह विंडो है जो प्रवाह के किसी घेरे से खुलती है। उसके भीतर के कार्ड ही उसके बच्चे हैं, जैसे ओवन, फ़्रिज या बर्तन धोने की मशीन।",
