  "It arrives: the tile is there.": "आ रही है: टाइल मौजूद है।",
  "It changes the drawing at the other end of the pipe: whoever has a boiler serving only the tank was shown a radiator they do not have.":
    "पाइप के दूसरे सिरे का चित्र बदल जाता है: जिसका बॉयलर सिर्फ़ टंकी को देता है उसे ऐसा रेडिएटर दिखता था जो उसके पास है ही नहीं।",
  "It did not work.": "यह नहीं हो पाया।",
  "It does not arrive. Check the address, and that the service lets this page read it.":
    "नहीं आती। पता जाँचिए, और यह भी कि सेवा यहाँ से पढ़ने देती है या नहीं।",
