  "It tells two agendas apart on the same day. Left automatic it gets one of its own, always the same.":
    "इससे एक ही दिन के दो कैलेंडर अलग दिखते हैं। स्वचालित छोड़ने पर इसे अपना रंग मिलता है, हमेशा वही।",
