  "No window sits in a room that has a hygrometer: pick the room in the window's row, below.":
    "कोई भी खिड़की ऐसे कमरे में नहीं है जिसमें नमी मापक हो: नीचे खिड़की की पंक्ति में कमरा चुनें।",
