  Shutters: "शटर",
  "Shutters and curtains show up on the 🪟 Windows page, grouped by floor and room. Every row accepts a cover.* entity — with position and percentages — or a switch.* relay: one when switching it on keeps the shutter up, two when one relay sends it up and another sends it down, like a Shelly in switch mode. When the window opens by hand — shutters, blinds, a handle — leave the command boxes empty and fill in the contact sensor alone: the card still draws it and says whether it is open.":
    "शटर और परदे 🪟 खिड़कियाँ पृष्ठ पर दिखते हैं, मंज़िल और कमरे के अनुसार समूहित। हर पंक्ति एक cover.* इकाई स्वीकार करती है — स्थिति और प्रतिशत के साथ — या एक switch.* रिले: एक, जब उसे चालू करने पर शटर ऊपर रहता है; दो, जब एक ऊपर भेजता है और दूसरा नीचे, जैसे स्विच मोड में Shelly। अगर खिड़की हाथ से खुलती है — पल्ले, झिलमिली, एक हैंडल — तो कमांड के खाने खाली छोड़ दें और सिर्फ़ खुलने का सेंसर भरें: कार्ड फिर भी बनता है और बताता है कि वह खुली है या नहीं।",
  "Shutters · Curtains · Contact sensors": "शटर · परदे · खुलने के सेंसर",
  "Sign path timeout": "पथ पर हस्ताक्षर करते समय समय समाप्त",
  "Simple alternative to the duration entity.": "अवधि इकाई का सरल विकल्प।",
