  Yes: "हाँ",
  "You can review, fix or remove every proposal from the editor.":
    "हर सुझाव को आप संपादक में देख, सुधार या हटा सकते हैं।",
  "You can use monthly entities or cumulative TOTALS: months are computed automatically.":
    "आप महीने की इकाइयाँ या जोड़ते जाने वाले कुल मान इस्तेमाल कर सकते हैं: महीने अपने आप गिने जाते हैं।",
  "You have mail": "आपकी डाक आई है",
  "You have not linked your entities yet, so the cards are hidden.":
    "आपने अभी अपनी इकाइयाँ नहीं जोड़ी हैं, इसलिए कार्ड छिपे हुए हैं।",
