  "last watered a day ago": "आख़िरी बार एक दिन पहले पानी दिया",
  "last watered an hour ago": "आख़िरी बार एक घंटे पहले पानी दिया",
  "Living room ficus": "बैठक का फ़ाइकस",
  "needs water": "पानी चाहिए",
  "Needs water below (%)": "इससे नीचे पानी चाहिए (%)",
  "needs water in ${giorni} days": "${giorni} दिन में पानी चाहिए",
  "needs water in a day": "एक दिन में पानी चाहिए",
  "needs water soon": "जल्द पानी चाहिए",
  "New plant": "नया पौधा",
  "No plant configured": "कोई पौधा सेट नहीं है",
  "Optional: the temperature sensor in the same pot. Leave it empty if yours only measures moisture.":
    "वैकल्पिक: उसी गमले का तापमान सेंसर। अगर आपका सेंसर सिर्फ़ नमी मापता है तो इसे खाली छोड़ दें।",
  outdoors: "बाहर",
  "Outdoors: if rain is coming, wait": "बाहर: अगर बारिश आने वाली है, तो रुकें",
  "Plant care": "पौधे",
  "Plant saved": "पौधा सहेजा गया",
