  "Soil at ${quanto}": "मिट्टी ${quanto} पर",
  "Soil temperature": "मिट्टी का तापमान",
  "Take the ${quante} soil sensors Home Assistant found":
    "Home Assistant को मिले ${quante} मिट्टी सेंसर ले आएँ",
  "The plants at home, one per row: the soil moisture sensor, the name, the drawing, and the temperature if there is one. The Plant care page says which need watering, which are waiting for rain and when the others will be due.":
    "घर के पौधे, हर पंक्ति में एक: मिट्टी की नमी का सेंसर, नाम, चित्र, और अगर हो तो तापमान। पौधे पेज बताता है कि किन्हें पानी देना है, कौन बारिश का इंतज़ार कर रहे हैं और बाकी की बारी कब आएगी।",
  "The rain will see to it": "बारिश संभाल लेगी",
  "The sensor stuck in the soil, in percent: Ecowitt, Tuya, Xiaomi.":
    "मिट्टी में लगा सेंसर, प्रतिशत में: Ecowitt, Tuya, Xiaomi.",
  "too wet": "बहुत गीली",
  "Too wet above (%)": "इससे ऊपर बहुत गीली (%)",
  "Unnamed plant": "बिना नाम का पौधा",
  "Until you pick the entity this plant is nowhere: not on the page, not on the Home tile.":
    "जब तक आप एंटिटी नहीं चुनते, यह पौधा कहीं नहीं है: न पेज पर, न होम की टाइल पर।",
  Waiting: "इंतज़ार में",
  "watered just now": "अभी पानी दिया गया",
  "When the soil is dry but the home weather forecasts rain in the next hours, the plant waits instead of asking for water. Only for those the rain really reaches.":
    "जब मिट्टी सूखी हो लेकिन घर का मौसम अगले कुछ घंटों में बारिश का अनुमान दे, तो पौधा पानी माँगने के बजाय इंतज़ार करता है। सिर्फ़ उन पौधों के लिए जिन तक बारिश सच में पहुँचती है।",
  "${quante} readings out of range": "${quante} मान सीमा से बाहर",
  "${ritardo} days late": "${ritardo} दिन की देरी",
  "After this many days the page and the Home tile say the water change is due.":
    "इतने दिनों के बाद पेज और होम की टाइल बताते हैं कि पानी बदलने का समय हो गया है।",
  "All in range": "सब कुछ सीमा में",
  Aquarium: "एक्वेरियम",
  "Done today": "आज किया",
  "due today": "आज करना है",
  "every ${ogni} days": "हर ${ogni} दिन",
  "every day": "हर दिन",
