  "Ideal from": "आदर्श से",
  "Ideal up to": "आदर्श तक",
  "It is recorded from the page with “Done today”; here you can correct it.":
    "इसे पेज से “आज किया” से दर्ज किया जाता है; यहाँ आप इसे सुधार सकते हैं।",
  "Last water change": "पिछली बार पानी बदला",
  Litres: "लीटर",
