  "Not recorded yet: tap “Done today” on the day you do it, and from then on the page counts the days.":
    "अभी दर्ज नहीं है: जिस दिन पानी बदलें उस दिन “आज किया” दबाएँ, फिर पेज दिन गिनेगा।",
