  "Remote control": "रिमोट कंट्रोल",
  "TV home screen": "टीवी की होम स्क्रीन",
  "TV menu": "टीवी मेनू",
  "The TV's arrows, OK, back, home screen and channels, under its card and only while the TV is on. It needs the TV's remote.* entity: Samsung (Samsung Smart TV integration), Sony Bravia, Philips, Android TV and Google TV, Apple TV, Roku. LG webOS TVs don't need it.":
    "टीवी के तीर, OK, पीछे, होम स्क्रीन और चैनल, उसके कार्ड के नीचे और सिर्फ़ टीवी चालू होने पर। इसके लिए टीवी की remote.* एंटिटी चाहिए: Samsung (Samsung Smart TV इंटीग्रेशन), Sony Bravia, Philips, Android TV और Google TV, Apple TV, Roku। LG webOS टीवी को इसकी ज़रूरत नहीं।",
  "These are in the house — one tap picks it:": "घर में ये हैं — एक टैप से चुन लें:",
  "Volume down": "आवाज़ कम करें",
  "Volume up": "आवाज़ बढ़ाएँ",
  "${quante} actions": "${quante} क्रियाएँ",
  "${quante} areas together: the buttons apply to all":
    "${quante} क्षेत्र एक साथ: बटन सभी पर लागू होते हैं",
  "Press and hold an area to pick more than one":
    "एक से अधिक चुनने के लिए किसी क्षेत्र को दबाकर रखें",
  "1 action": "1 क्रिया",
  "Close the ${nome} group": "${nome} समूह बंद करें",
  "Open the ${nome} group": "${nome} समूह खोलें",
  "The group is optional: actions with the same group sit together on Home, under a title that says how many are on and closes with a tap. Without groups it stays a single row.":
    "समूह वैकल्पिक है: एक ही समूह की क्रियाएँ होम पर एक साथ रहती हैं, एक शीर्षक के नीचे जो बताता है कि कितनी चालू हैं और एक टैप से बंद होता है। बिना समूहों के यह एक ही पंक्ति रहती है।",
  "e.g. Lights, Shutters": "जैसे लाइटें, शटर",
  "💾 Group saved": "💾 समूह सहेजा गया",
  "1 open · tap to close": "1 खुला · बंद करने के लिए स्पर्श करें",
  "open · tap to close": "खुले · बंद करने के लिए स्पर्श करें",
  "1 open now · closed by hand": "1 अभी खुला · हाथ से बंद होता है",
  "open now · closed by hand": "अभी खुले · हाथ से बंद होते हैं",
  "1 unlocked · tap to lock": "1 अनलॉक · लॉक करने के लिए स्पर्श करें",
  "unlocked · tap to lock": "अनलॉक · लॉक करने के लिए स्पर्श करें",
  "Door or window": "दरवाज़ा या खिड़की",
  Doors: "दरवाज़े",
  Locks: "ताले",
  "lock unlocked": "ताला खुला",
  "locks unlocked": "ताले खुले",
  "shutter open": "शटर खुला",
  "shutters open": "शटर खुले",
  "Under the weather, open doors and open windows are two pills. By default the class Home Assistant gives the contact decides; pick here when it is not the right one.":
    "मौसम के नीचे खुले दरवाज़े और खुली खिड़कियाँ दो अलग गोलियाँ हैं। डिफ़ॉल्ट रूप से Home Assistant द्वारा संपर्क को दी गई श्रेणी तय करती है; जब वह सही न हो तो यहाँ चुनें।",
  "If the camera already has its own integration in Home Assistant — Reolink, Tapo, Hikvision — the entity is already there: pick it in the field above, and the video goes through it.":
    "अगर कैमरे का Home Assistant में पहले से अपना इंटीग्रेशन है — Reolink, Tapo, Hikvision — तो इकाई पहले से मौजूद है: उसे ऊपर वाले खाने में चुनें, और वीडियो उसी से आएगा।",
  "The stream name only works with the dashboard opened outside Home Assistant: in here it cannot be reached, and the camera goes through its entity.":
    "स्ट्रीम का नाम तभी काम करता है जब डैशबोर्ड Home Assistant के बाहर खुला हो: यहाँ अंदर उस तक पहुँचा नहीं जा सकता, और कैमरा अपनी इकाई से चलता है।",
  "HLS: skipped, Home Assistant declares no stream for this camera":
    "HLS: छोड़ा गया, Home Assistant इस कैमरे के लिए कोई स्ट्रीम घोषित नहीं करता",
  "WebRTC: the go2rtc stream name only works with the dashboard opened outside Home Assistant — in here the camera goes through its entity":
    "WebRTC: go2rtc स्ट्रीम नाम तभी काम करता है जब डैशबोर्ड Home Assistant के बाहर खुला हो — यहाँ अंदर कैमरा अपनी इकाई से चलता है",
  "WebRTC: tried first with its full time, the video did not arrive":
    "WebRTC: पहले पूरे समय के साथ आज़माया गया, वीडियो नहीं आया",
  Bypass: "बायपास करें",
  "Bypass from the alarm?": "अलार्म से बायपास करें?",
  "Bypassed from the alarm": "अलार्म से बायपास",
