  "above the ${soglia} threshold": "${soglia} की सीमा से ऊपर",
  "Add pack": "पैक जोड़ें",
  "An entity, or the number printed on the pack label with its unit. With every pack's capacity the overall charge is weighted by energy, and the page says when it will be full or empty.":
    "एक एंटिटी, या पैक के लेबल पर छपी संख्या उसकी इकाई के साथ। हर पैक की क्षमता से कुल चार्ज को ऊर्जा के हिसाब से तौला जाता है, और पेज बताता है कि वह कब भरेगा या खाली होगा।",
