  Terrariums: "टेरारियम",
  "The pets of the house: one card each, with its photo and what concerns it — the bowl, the litter box, the water, the microchip door, the collar. Aquariums and terrariums too, as many as you have: each with its own entities.":
    "घर के पालतू जानवर: हर एक का अपना कार्ड, उसकी फ़ोटो और उससे जुड़ी हर चीज़ के साथ — कटोरा, लिटर बॉक्स, पानी, माइक्रोचिप वाला दरवाज़ा, पट्टा। एक्वेरियम और टेरारियम भी, जितने आपके पास हों: हर एक अपनी एंटिटी के साथ।",
