  "Opens on": "इस पर खुलता है",
  "Page type": "पेज का प्रकार",
  "Shown on the tab at the top": "ऊपर के टैब पर दिखता है",
  "The wall tablet's panel. Choose the pages — the tabs at the top — and what each one holds. On the tablet, holding the clock for two seconds brings you back here.":
    "दीवार टैबलेट का पैनल। पेज — ऊपर के टैब — और हर एक में क्या हो, चुनें। टैबलेट पर घड़ी को दो सेकंड दबाए रखने से आप यहाँ लौट आते हैं।",
