    "पेज बाईं ओर बड़े बटनों के एक कॉलम में, जैसे कंट्रोल रूम पैनलों में। केवल लैंडस्केप में: पोर्ट्रेट में और छोटी स्क्रीन पर ऊपर के टैब ही रहते हैं",
