  "1 thing to do": "करने को 1 काम",
  "A smoke or gas detector is going off.": "धुएँ या गैस का डिटेक्टर बज रहा है।",
  "Adjust the climate?": "क्लाइमेट समायोजित करें?",
  "Alarm: ${nomi(accesi, l)}": "अलार्म: ${nomi(accesi, l)}",
  "An appointment": "एक अपॉइंटमेंट",
  "and ${altre} more": "और ${altre} अन्य",
  Arm: "सक्रिय करें",
  "Arm it in away mode?": "इसे बाहर वाले मोड में सक्रिय करूँ?",
  Ask: "पूछें",
  "Ask the house…": "घर से पूछें…",
  "Battery low: ${prima.name}": "बैटरी लगभग खत्म: ${prima.name}",
  "Better close it first.": "पहले बंद कर देना बेहतर है।",
  "Charge ${auto} on solar": "${auto} को सौर से चार्ज करें",
  "Close it?": "बंद कर दूँ?",
  "CO₂ at ${ppm} ppm: open a window for a few minutes.":
    "CO₂ ${ppm} ppm: कुछ मिनट के लिए खिड़की खोलें।",
  "Collection is this morning.": "कचरा आज सुबह उठेगा।",
  "Collection is tomorrow morning.": "कचरा कल सुबह उठेगा।",
  "Empty for ${durata(da, l)}: turn them off?": "${durata(da, l)} से खाली: बंद कर दूँ?",
  "Everyone has left, but the alarm is off": "सब बाहर चले गए, पर अलार्म बंद है",
