  "Everything is fine at home.": "घर में सब ठीक है।",
  "For ${durata(f.daMs, l)}.": "${durata(f.daMs, l)} से।",
  "For more than two hours.": "दो घंटे से ज़्यादा से।",
  "Forget what it has learned": "जो सीखा है उसे भूल जाएँ",
  "From the home calendar.": "घर के कैलेंडर से।",
  "House assistant": "घर का सहायक",
  "How much it says": "कितना बताए",
  "I'll write here if something needs doing.": "कुछ करना होगा तो यहाँ लिखूँगा।",
  idea: "सुझाव",
  "In 1 h": "1 घंटे में",
  "It's late and ${accese.length} lights are still on":
    "देर हो गई है और ${accese.length} लाइटें अब भी जल रही हैं",
  "It's late and ${accese[0].name} is still on":
    "देर हो गई है और ${accese[0].name} अब भी जल रही है",
  "It's night and ${g.name} is open": "रात है और ${g.name} खुला है",
  "It's night and ${nomi(aperte, l)} is unlocked": "रात है और ${nomi(aperte, l)} पर ताला नहीं है",
  "It's plugged in and ${kw} kW are spare.": "यह प्लग इन है और ${kw} kW बच रहे हैं।",
  "It's raining": "बारिश हो रही है",
  "Let some air in.": "थोड़ी हवा आने दें।",
  "Lock it?": "ताला लगा दूँ?",
  Next: "इसके बाद",
  "Night starts at": "रात शुरू होती है",
  "No rush, when you have a minute.": "कोई जल्दी नहीं, जब एक मिनट मिले।",
  "Nobody is home, but ${accese.length} lights are on":
    "घर पर कोई नहीं है, पर ${accese.length} लाइटें जल रही हैं",
