  "Nobody is home, but ${nomi(accesi, l)} is playing":
    "घर पर कोई नहीं है, पर ${nomi(accesi, l)} चल रहा है",
  "Nobody is home, but the climate is on: ${nomi(accesi, l)}":
    "घर पर कोई नहीं है, पर क्लाइमेट चालू है: ${nomi(accesi, l)}",
  "Nobody is in those rooms.": "उन कमरों में कोई नहीं है।",
  "Not now": "अभी नहीं",
  "Nothing else for now": "अभी और कुछ नहीं",
  "On for over an hour.": "एक घंटे से ज़्यादा से चालू।",
  "Only what matters": "सिर्फ़ ज़रूरी",
