  "A sensor that names the zone. Empty: the house looks at which door, window or motion turned on last.": "ज़ोन बताने वाला सेंसर। खाली: घर देखता है कि आख़िरी बार कौन सा दरवाज़ा, खिड़की या मोशन चालू हुआ।",
