  "The entity that says the alarm is going off: a switch, a sensor or a helper. When it reads “triggered” Security, the Home tile and the wall panel turn red, and the house sends the urgent notification.": "वह एंटिटी जो बताती है कि अलार्म बज रहा है: स्विच, सेंसर या हेल्पर। जब यह “ट्रिगर” हो तो सुरक्षा, होम टाइल और दीवार पैनल लाल हो जाते हैं और घर तत्काल सूचना भेजता है।",
