  "The meter that measures it: it shows up in that plant's flow.": "जो मीटर इसे मापता है: यह उसी प्लांट के फ़्लो में दिखता है।",
  "The rooms have no floor: you can set one in the Rooms page of the config.": "कमरों की कोई मंज़िल नहीं: आप इसे कॉन्फ़िग के कमरे पेज में चुन सकते हैं।",
  "The rooms on the chosen floors go to this plant by themselves, with their appliances.": "चुनी हुई मंज़िलों के कमरे अपने उपकरणों सहित अपने आप इस प्लांट में जाते हैं।",
